import re
from abc import abstractproperty, ABCMeta, abstractmethod
from socket import socket, AF_INET, SOCK_STREAM

from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import RfSwitchActionFailed, RfSwitchActionNotSupported


class RFLight34980A(RfSwitch):
    def __init__(self, ip, port):
        """ ip: str, port: str | int """
        super().__init__()
        self.connector = SocketAdapter(ip, port)

    def disconnect_ports(self, port_in=0, port_out=0):
        """ port_in: int, port_out: Literal[0] """
        response = self.open_all_ports()
        return self._verify_set_query_response(response)

    def connect_ports(self, port_in, port_out=0):
        """ port_in: int, port_out: Literal[0], returns: bool """
        response = self.connector.query(f"ROUTE:PATHSWITCH:{port_in}:0")
        return self._verify_set_query_response(response)

    def get_port_in_status(self, port_in):
        return port_in == self.get_connected_ports()

    def get_port_out_status(self, port_out=0):
        """ port_out: Literal[0] """
        return self.get_connected_ports() is not None

    def get_connected_ports(self):
        """ Only one port can be connected """
        response = self.connector.query("ROUTE:PATHSWITCH?")
        port = int(response.rstrip()[len('REROUTE:PATHSWITCH:'):].split(' ')[0])
        return port if port != 0 else None

    def open_all_ports(self):
        """ Disconnects all ports. """
        return self.connector.query('ROUTE:PATHSWITCH:0:0')

    def _verify_set_query_response(self, response):
        return response.split(' ')[1].rstrip() == 'OK'


class BaseNTmXnNS(RfSwitch, metaclass=ABCMeta):
    """
    Base class for RFlight Switch Matrix.
    """

    def __init__(self, ip="192.168.1.68", port=3000):
        super().__init__()
        self.ip = ip
        self.port = int(port)
        self._client_socket = None

    @property
    def client_socket(self):
        """Property to create socket connection on demand."""
        if self._client_socket is None:
            self._client_socket = socket(AF_INET, SOCK_STREAM)
            self._client_socket.settimeout(30.0)
            self._client_socket.connect((self.ip, self.port))
        return self._client_socket

    @abstractproperty
    def SUPPORTED_PORT_IN_VALUES(self):
        # type: () -> list[str]
        """List of supported port ins."""

    @abstractproperty
    def SUPPORTED_PORT_OUT_VALUES(self):
        # type: () -> list[str]
        """List of supported port outs."""

    def connect_ports(self, port_in, port_out):
        # type: (str, str) -> None
        """
        Connect RF switch input port to output port.
        Firstly checks if there is connected correct RFlight switch.
        :param str port_in: RF switch input port: eg: string with single port number from range <1:4>
        :param str port_out: RF switch output port: eg: string with single port number from range <0:64>
        """
        recv = self._execute_command('*IDN?')
        self._verify_device_name_in_response(recv)
        self._connect_single_port(port_in, port_out)

    def disconnect_ports(self, port_in=None, port_out=None):
        # type: (str, str) -> None
        """
        Code to disconnect RF switch input port from output port.
        """
        raise RfSwitchActionNotSupported("Disconnecting ports action not supported for this device.")

    def get_port_in_status(self, port_in):
        # type: (str) -> None
        """
        Get RF switch input port status.
        """
        raise RfSwitchActionNotSupported("Getting port_in status action not supported for this device.")

    def get_port_out_status(self, port_out):
        # type: (str) -> None
        """
        Get RF switch output port status.
        """
        raise RfSwitchActionNotSupported("Getting port_out status action not supported for this device.")

    def get_connected_ports(self):
        # type: () -> dict[str, str]
        """
        Returns current configuration of ports.
        Eg: {'1': '1'}, means port_in=1 is connected to port_out=1
        """
        ports_out = self._get_full_port_out_configuration()
        connected_ports = dict(zip(self.SUPPORTED_PORT_IN_VALUES, ports_out))
        return connected_ports

    @abstractmethod
    def _verify_device_name_in_response(self, idn_response):
        # type: (str) -> None
        """Raises if expected device name is not in response.
        Example of response: 'Rflight, NT-m*nNS, P/N14120001, Rev.1.0.0'
        """

    def _validate_port_in_value(self, port_in):
        # type: (str) -> None
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            raise RfSwitchActionFailed(f"Given port_in: {port_in} is not supported.")

    def _validate_port_out_value(self, port_out):
        # type: (str) -> None
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f"Given port_out: {port_out} is not supported.")

    def _connect_single_port(self, port_in, port_out):
        # type: (str, str) -> None
        """Method that connect single port_in to port_out.
        Rest of ports that are already set in switch stays the same.
        Method validates port in and port out if they are in allowed range.
        """
        self._validate_port_in_value(port_in)
        self._validate_port_out_value(port_out)
        ports_out = self._get_full_port_out_configuration()
        ports_out[int(port_in) - 1] = port_out
        self._operate_ports(ports_out)

    def _operate_ports(self, ports_out):
        # type: (list[str]) -> None
        """Gets port out list. Sends execute query and validates response."""
        ports_out = ":".join(ports_out)
        enable_command = f"ROUTE:PATHSWITCH:{ports_out}:0"
        response = self._execute_command(enable_command)
        if not re.match(f"REROUTE:PATHSWITCH:{ports_out}.*OK", response):
            raise RfSwitchActionFailed(f"Enable out_ports: {ports_out} error. RFlight response: {response}")

    def _get_full_port_out_configuration(self):
        # type: () -> list[str]
        """Sends query and get port out configuration.
        Response for command: ROUTE:PATHSWITCH?
            Should be string, like:
                REROUTE:PATHSWITCH:14
                or
                REROUTE:PATHSWITCH:14:15:16:17:0:OK
        Each switch should implement its own regex port matching.
        :return list of connected ports eg: ['14'], or ['14', '15', '16', '17']"""
        response = self._execute_command("ROUTE:PATHSWITCH?")
        re_catch_ports = self._regex_port_matching()
        match_obj = re.match(re_catch_ports, response)
        ports_out = match_obj.groups()
        return list(ports_out)

    @staticmethod
    @abstractmethod
    def _regex_port_matching():
        # type: () -> str
        r"""Get a regex that should be matching for 'ROUTE:PATHSWITCH?' command.
        Each switch should implement its own regex port matching.
        :return str eg: r"REROUTE:PATHSWITCH:(\d+):(\d+):(\d+):(\d+):\d+:OK"
        """

    def _execute_command(self, command):
        # type: (str) -> str
        """Send and get response using socket connection."""
        command += '\r\n'
        command = command.encode()
        self.client_socket.send(command)
        recv = self._receive()
        if len(recv) == 0:
            raise RfSwitchActionFailed("Received empty response from the device.")
        return recv

    def _receive(self):
        # type: () -> str
        # response example: 'REROUTE:PATHSWITCH:14:9:10:1:0:OK'
        response = self.client_socket.recv(1024)
        response = response.replace(b'\x00', b'')
        return response.decode()


class NT4X64NS(BaseNTmXnNS):
    """
    Module to control NT-4X64NS switch matrix.
    """

    SUPPORTED_PORT_OUT_VALUES = [str(value) for value in range(65)]
    SUPPORTED_PORT_IN_VALUES = ["1", "2", "3", "4"]

    def _verify_device_name_in_response(self, idn_response):
        # type: (str) -> None
        if "NT-4X64NS" not in idn_response:
            raise RfSwitchActionFailed("Expected model: NT-4X64NS not found in device response.")

    @staticmethod
    def _regex_port_matching():
        # type: () -> str
        return r"REROUTE:PATHSWITCH:(\d+):(\d+):(\d+):(\d+):\d+:OK"


class NT1X64NS(BaseNTmXnNS):
    """
    Module to control NT-1X64NS switch matrix.
    """

    SUPPORTED_PORT_OUT_VALUES = [str(value) for value in range(65)]
    SUPPORTED_PORT_IN_VALUES = ["1"]

    def disconnect_ports(self, port_in=None, port_out=None):
        # type: (str, str) -> None
        """
        Code to disconnect RF switch input port from output port.
        For NT-1*nNS '0' means the channel switched off.
        """
        self.connect_ports(port_in, "0")

    def _verify_device_name_in_response(self, idn_response):
        # type: (str) -> None
        if "NT-1X64NS" not in idn_response:
            raise RfSwitchActionFailed("Expected model: NT-1X64NS not found in device response.")

    @staticmethod
    def _regex_port_matching():
        # type: () -> str
        return r"REROUTE:PATHSWITCH:(\d+)"


