class SocketAdapter:
    def __init__(self, ip, port):
        """ ip: str, port: str | int """
        self.instrument = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.instrument.connect((ip, port))

    def query(self, command):
        """ command: str """
        self.write(command)
        return self.read()

    def write(self, command):
        """ command: str """
        self.instrument.sendall(f"{command}\r\n".encode())

    def read(self, bytes_chunk=1024):
        """ bytes_chunk: int """
        return self.instrument.recv(bytes_chunk).decode("utf-8")

    def __del__(self):
        self.instrument.close()
